const svg=(name,size=18)=>{const p={share:'<path d="M12 16V3m-5 5 5-5 5 5M5 12v8h14v-8"/>',search:'<circle cx="10.8" cy="10.8" r="6.5"/><path d="m16 16 5 5"/>',heart:'<path d="M20.8 8.4c0 4-8.8 9.6-8.8 9.6S3.2 12.4 3.2 8.4A4.8 4.8 0 0 1 12 5.8a4.8 4.8 0 0 1 8.8 2.6Z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',check:'<path d="m4 12 5 5L20 6"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||''}</svg>`};
const $=s=>document.querySelector(s), shell=$('#shell'),app=$('#app');
const tabs=['Рекомендации','Оценённые','Избранное','Хочу посмотреть','Просмотрено'],types=['Все','Фильм','Сериал','Аниме','Мультфильм'],typeLabels=['Все','Фильмы','Сериалы','Аниме','Мультфильмы'];
