let theme='experimental',page='profile',tab='Рекомендации',filter='Все',focus=0,query='',saved=new Set([0,2,5]),planned=new Set([3,7]),watched=new Set([0,1,2,4,5,6]),recs=new Map([0,1,2,3,4,5,6,7].map(i=>[i,films[i].desc])),ratings=new Map([0,1,2,4,5,6].map(i=>[i,{scores:[films[i].rate,...Array(7).fill(null)],emotions:[],comment:''}])),draft=null,current=null,toastTimer,hoverTimer;
