function total(scores){if(scores[0]==null)return null;let rest=scores.slice(1).filter(v=>v!==null);let n=rest.length?(scores[0]+rest.reduce((a,b)=>a+b,0)/rest.length)/2:scores[0];return Math.round((n+Number.EPSILON)*10)/10}
function rating(i){return ratings.has(i)?total(ratings.get(i).scores):null}
