function nav(){return `<header class="nav"><a class="brand" href="/" aria-label="Filmoteka — главная"><span class="mark"><i></i><i></i><i></i><i></i></span>filmoteka<span style="color:var(--accent)">.</span></a><div class="navlinks">${[['catalog','Каталог'],['profile','Мой профиль'],['library','Библиотека']].map(([p,n])=>`<button data-page="${p}" class="${page===p?'on':''}">${n}</button>`).join('')}</div><div class="navright"><button class="iconbutton" data-action="search" aria-label="Поиск">${svg('search')}</button><button class="avatar" data-page="profile" aria-label="Профиль">F</button></div></header>`}
function hero(){return `<section class="hero ${customBackground?'custom-background':''}" id="hero"><div class="hero-back"><div class="base-scene ${customBackground?'photo':'default-art'}" ${customBackground?`style="background-image:url('${customBackground}')"`:''}></div></div><div class="hero-title"><div class="profile-row"><div class="avatar large">F</div><div class="identity"><div class="name-row"><h1>Filmlover</h1><button class="share-icon" data-action="share" title="Поделиться профилем" aria-label="Поделиться профилем">${svg('share',19)}</button></div><small>@filmlover</small></div></div></div><div class="scene-control"><button class="scene-edit" data-action="edit-bg" title="Загрузить фон профиля" aria-label="Загрузить фон профиля"><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8" cy="9" r="1.5"/><path d="m3 17 6-5 4 4 3-3 5 4"/></svg></button>${customBackground?'<button class="scene-edit" data-action="reset-bg" title="Сбросить свой фон" aria-label="Сбросить свой фон">×</button>':''}<input type="file" id="background-file" accept="image/png,image/jpeg,image/webp" hidden></div></section>`}
function indices(){let ix=films.map((_,i)=>i);if(page!=='catalog'){if(tab==='Рекомендации')ix=ix.filter(i=>recs.has(i));if(tab==='Оценённые')ix=ix.filter(i=>ratings.has(i));if(tab==='Избранное')ix=ix.filter(i=>saved.has(i));if(tab==='Хочу посмотреть')ix=ix.filter(i=>planned.has(i));if(tab==='Просмотрено')ix=ix.filter(i=>watched.has(i))}if(filter!=='Все')ix=ix.filter(i=>films[i].type===filter);if(query)ix=ix.filter(i=>(films[i].name+' '+films[i].en).toLowerCase().includes(query.toLowerCase()));return ix}
function cards(){return indices().map((i,j)=>{let f=films[i],r=rating(i);return `<article tabindex="0" class="film" data-film="${i}" style="--i:${j}" aria-label="Открыть ${esc(f.name)}"><div class="cover"><div class="art" style="background-image:url('${ART[i]}')"></div><div class="card-glint"></div>${r===null?'':`<span class="rating">${fmt(r)}</span>`}<div class="art-text"><small>${esc(f.en)}</small><strong>${esc(f.name)}</strong></div><div class="quick-actions"><button data-open="${i}">${svg('arrow',13)} ${r===null?'Оценить':'Открыть'}</button><button data-planquick="${i}" aria-label="Хочу посмотреть" aria-pressed="${planned.has(i)}" class="${planned.has(i)?'on':''}">${svg('bookmark',15)}</button><button data-heart="${i}" aria-label="Избранное" aria-pressed="${saved.has(i)}" class="${saved.has(i)?'on':''}">${svg('heart',15)}</button></div></div><div class="film-info"><div><h3>${esc(f.name)}</h3><div class="meta">${f.year} · ${f.type}</div></div><button class="heart ${saved.has(i)?'saved':''}" data-heart="${i}" aria-label="Избранное" aria-pressed="${saved.has(i)}">${svg('heart',18)}</button></div>${tab==='Рекомендации'&&page!=='catalog'?`<p class="description">${esc(recs.get(i))}</p>`:''}</article>`}).join('')||'<p class="empty">Здесь пока нет произведений.</p>'}
function section(){const title=page==='catalog'?'Каталог':tab==='Рекомендации'?'Советую посмотреть':tab==='Оценённые'?'Мои оценки':tab;return `<section class="content" id="collection"><div class="section-head"><div><h2>${title}</h2><p>${indices().length} ${indices().length===1?'произведение':indices().length>=2&&indices().length<=4?'произведения':'произведений'}</p></div><div class="filter">${types.map((x,i)=>`<button data-filter="${x}" class="${filter===x?'on':''}">${typeLabels[i]}</button>`).join('')}</div></div><div class="film-grid" id="grid">${cards()}</div><p class="art-credit">Демонстрационные данные и иллюстрации · не официальные постеры</p></section>`}
function positionTab(){let bar=$('.profiletabs'),active=bar?.querySelector('button.on'),indicator=bar?.querySelector('.tab-indicator');if(active&&indicator){indicator.style.width=active.offsetWidth+'px';indicator.style.transform=`translateX(${active.offsetLeft}px)`}}
function home(){return `<section class="home-intro" aria-labelledby="home-title"><div class="home-copy"><h1 id="home-title">Кино, которое<br>остаётся с вами.</h1><p>Сохраняйте впечатления от фильмов, сериалов и аниме. Собирайте свою библиотеку и советуйте то, что хочется разделить.</p><div class="home-actions"><button class="primary" data-page="catalog">Открыть каталог</button><button class="secondary" data-page="profile">Мой профиль</button></div></div><div class="home-art" aria-hidden="true"><img src="${ART[2]}" alt="" width="360" height="520"><img src="${ART[0]}" alt="" width="360" height="520"><img src="${ART[1]}" alt="" width="360" height="520"></div></section><section class="home-paths" aria-label="Возможности"><div><h2>Найти свою историю</h2><p>Выберите произведение в каталоге и сохраните на потом.</p><button data-page="catalog">Перейти в каталог</button></div><div><h2>Сохранить впечатление</h2><p>Оценка, эмоции и комментарий — то, каким просмотр был для вас.</p><button data-page="library">Открыть библиотеку</button></div><div><h2>Посоветовать близким</h2><p>Рекомендации с вашим объяснением, почему стоит посмотреть.</p><button data-page="profile">Открыть профиль</button></div></section>`}
function navigate(next,push=true){page=next;filter='Все';query='';if(page==='library')tab='Оценённые';if(page==='profile')tab='Рекомендации';if(push)history.pushState({page},'',page==='home'?'/':`/prototype/?view=${page}`);render();const h=$('h1')||$('.section-head h2');h.tabIndex=-1;h.focus({preventScroll:true});window.scrollTo(0,0)}
