document.addEventListener('click',e=>{const link=e.target.closest('a.brand');if(link&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey&&e.button===0){e.preventDefault();navigate('home')}});
function render(){shell.className='wrap '+(page==='catalog'?'catalog':'');shell.innerHTML=nav()+(page==='home'?home():`<div class="searchbox ${page==='catalog'?'on':''}"><input type="search" id="q" placeholder="Название фильма, сериала или аниме" aria-label="Поиск произведения" value="${esc(query)}"></div>`+(page==='catalog'?'':hero())+`<div class="profiletabs" aria-label="Библиотека">${tabs.map(t=>`<button aria-pressed="${tab===t}" data-tab="${t}" class="${tab===t?'on':''}">${t}</button>`).join('')}<span class="tab-indicator"></span></div>`+section())+`<footer class="footer"><strong>Filmoteka.</strong><span>Прототип · данные и фото до перезагрузки</span></footer>`;positionTab();focus=-1;app.style.setProperty('--scene-color','#d7c2f0')}
function changeFocus(i){if(page==='catalog')return;focus=i;const card=document.querySelector(`[data-film="${i}"]`);card?.style.setProperty('--card-light',colors[i])}
function restoreBackground(){focus=-1}
function updateSection(){const active=document.activeElement;const key=active?.outerHTML;let old=$('#collection');if(old)old.outerHTML=section();document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('on',x.dataset.tab===tab);x.setAttribute('aria-pressed',String(x.dataset.tab===tab))});positionTab();if(key&&!active.isConnected){const next=[...shell.querySelectorAll('button')].find(b=>b.outerHTML===key||['heart','planquick'].some(k=>active.dataset[k]!==undefined&&b.dataset[k]===active.dataset[k]));if(next)next.focus();else{const h=$('.section-head h2');h.tabIndex=-1;h.focus();}}}
function criterion(i){const v=draft.scores[i];return `<div class="criterion ${i===0?'main-criterion':''} ${v===null?'unset':''}" data-criterion="${i}"><label for="criterion-${i}"><span>${criteria[i]}</span><output>${v===null?'Не оценено':fmt(v)+'/10'}</output></label><div class="range-row"><input type="range" min="0" max="10" step="0.1" id="criterion-${i}" data-score="${i}" value="${v??5}" aria-label="${criteria[i]}"><button type="button" data-setscore="${i}" aria-label="${v===null?'Установить':'Очистить'}: ${criteria[i]}" title="${v===null?'Установить значение':'Очистить критерий'}">${v===null?'+':'×'}</button></div></div>`}
function openFilm(i){current=i;let f=films[i],old=ratings.get(i);draft={scores:old?[...old.scores]:Array(8).fill(null),emotions:new Set(old?.emotions||[]),comment:old?.comment||'',rec:recs.get(i)||''};let dlg=$('#dialog');dlg.innerHTML=`<div class="modal"><button class="close" data-action="close" aria-label="Закрыть">${svg('close')}</button><div class="modal-art" style="background-image:url('${ART[i]}')"></div><div class="modal-body"><div class="eyebrow">${f.type} · ${f.year}</div><h2>${esc(f.name)}</h2><div class="modal-controls"><button class="secondary ${saved.has(i)?'on':''}" data-toggle="fav">${svg('heart',16)} <span>${saved.has(i)?'В избранном':'В избранное'}</span></button><button class="secondary ${planned.has(i)?'on':''}" data-toggle="plan">${svg('bookmark',16)} <span>${planned.has(i)?'В планах':'Хочу посмотреть'}</span></button><button class="secondary ${watched.has(i)?'on':''}" data-toggle="watch">${svg('check',16)} <span>${watched.has(i)?'Просмотрено':'Отметить просмотр'}</span></button></div><div class="modal-rating"><div class="scoreboard"><div><h3>Моя оценка</h3><div class="meta" id="score-help"></div></div><div class="score-value"><span id="score">${fmt(total(draft.scores))}</span><small> / 10</small></div></div><div class="criteria">${criteria.map((_,i)=>criterion(i)).join('')}</div><label class="form-label">Какие эмоции я испытал?</label><div class="emotion-list">${emotions.map(e=>`<button class="emotion ${draft.emotions.has(e)?'on':''}" data-emotion="${e}" aria-pressed="${draft.emotions.has(e)}">${e}</button>`).join('')}</div><label for="comment" class="form-label">Комментарий</label><textarea id="comment" placeholder="Что запомнилось после просмотра?">${esc(draft.comment)}</textarea><div class="modal-actions"><button class="primary" data-action="save-rating" id="save-rating">Сохранить оценку</button><span class="meta">Эмоции и комментарий не влияют на балл.</span></div><div class="rec-box"><label for="recommendation" class="form-label">Рекомендация</label><textarea id="recommendation" placeholder="Почему ты советуешь это произведение?">${esc(draft.rec)}</textarea><div class="modal-actions"><button class="secondary" data-action="save-rec">${recs.has(i)?'Обновить рекомендацию':'Порекомендовать'}</button>${recs.has(i)?'<button class="secondary" data-action="delete-rec">Убрать рекомендацию</button>':''}</div></div></div></div></div>`;refreshScore();returnFocus=document.activeElement;dlg.classList.add('open');dlg.showModal();document.body.style.overflow='hidden';dlg.querySelector('.close').focus()}
function refreshScore(){let n=draft.scores.slice(1).filter(v=>v!==null).length;$('#score').textContent=fmt(total(draft.scores));$('#score-help').textContent=draft.scores[0]===null?'Сначала укажи общее впечатление':n?`50% общее впечатление + 50% среднее (${n} из 7 критериев)`:'Только общее впечатление · дополнительные критерии необязательны';$('#save-rating').disabled=false}
function changeScore(i,v){const input=$(`#criterion-${i}`);input.removeAttribute('aria-invalid');input.removeAttribute('aria-describedby');draft.scores[i]=v;let c=$(`[data-criterion="${i}"]`);c.classList.toggle('unset',v===null);c.querySelector('output').textContent=v===null?'Не оценено':fmt(v)+'/10';c.querySelector('button').textContent=v===null?'+':'×';c.querySelector('button').title=v===null?'Установить значение':'Очистить критерий';c.querySelector('button').setAttribute('aria-label',`${v===null?'Установить':'Очистить'}: ${criteria[i]}`);refreshScore()}
function closeFilm(){const id=current;const selector=returnFocus?.matches('[data-film]')?'':returnFocus?.hasAttribute('data-open')?' [data-open]':'';$('#dialog').classList.remove('open');$('#dialog').close();document.body.style.overflow='';current=null;draft=null;updateSection();(document.querySelector(`[data-film="${id}"]${selector}`)||$('.section-head h2'))?.focus();}
function toggleSet(set,i){set.has(i)?set.delete(i):set.add(i);return set.has(i)}
function share(){toast('Обмен профилем появится после согласования доступа.')}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(b){let d=b.dataset;if(d.theme){theme=d.theme;app.dataset.theme=theme;document.querySelectorAll('.lab-tabs button').forEach(x=>x.classList.toggle('active',x===b));render();return}if(d.page){navigate(d.page);return}if(d.tab){tab=d.tab;filter='Все';updateSection();return}if(d.filter){filter=d.filter;updateSection();return}if(d.open!==undefined){openFilm(+d.open);return}if(d.heart!==undefined||d.planquick!==undefined){let fav=d.heart!==undefined,i=+(fav?d.heart:d.planquick),on=toggleSet(fav?saved:planned,i);updateSection();toast(on?(fav?'Добавлено в избранное':'Добавлено в планы'):'Удалено из списка');return}if(d.toggle){let set={fav:saved,plan:planned,watch:watched}[d.toggle],on=toggleSet(set,current);b.classList.toggle('on',on);b.querySelector('span').textContent={fav:on?'В избранном':'В избранное',plan:on?'В планах':'Хочу посмотреть',watch:on?'Просмотрено':'Отметить просмотр'}[d.toggle];return}if(d.setscore!==undefined){let i=+d.setscore;changeScore(i,draft.scores[i]===null?Number($(`#criterion-${i}`).value):null);return}if(d.emotion){toggleSet(draft.emotions,d.emotion);b.classList.toggle('on',draft.emotions.has(d.emotion));b.setAttribute('aria-pressed',String(draft.emotions.has(d.emotion)));return}if(d.action==='save-rating'){if(!validDraft())return;ratings.set(current,{scores:[...draft.scores],emotions:[...draft.emotions],comment:$('#comment').value});closeFilm();toast('Оценка сохранена в прототипе');return}if(d.action==='save-rec'){recs.set(current,$('#recommendation').value);closeFilm();toast('Рекомендация сохранена в прототипе');return}if(d.action==='delete-rec'){recs.delete(current);closeFilm();toast('Рекомендация удалена');return}if(d.action==='share'){share();return}if(d.action==='edit-bg'){$('#background-file').click();return}if(d.action==='reset-bg'){customBackground='';render();$('[data-action=edit-bg]').focus();return}if(d.action==='search'){navigate('catalog');$('#q').focus();return}if(d.action==='close'){closeFilm();return}}
let f=e.target.closest('[data-film]');if(f)openFilm(+f.dataset.film);if(e.target===$('#dialog'))closeFilm()});
document.addEventListener('input',e=>{let t=e.target;if(t.id==='q'){query=t.value;updateSection()}if(t.dataset.score!==undefined)changeScore(+t.dataset.score,Number(t.value));if(t.id==='motion'){document.body.classList.toggle('no-motion',!t.checked);clearTimeout(hoverTimer);clearTimeout(restoreTimer);restoreBackground()}});
document.addEventListener('change',e=>{if(e.target.id!=='background-file')return;let f=e.target.files?.[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>15*1024*1024){toast('Выбери PNG, JPEG или WebP до 15 МБ');return}let reader=new FileReader();reader.onload=()=>{let img=new Image();img.onload=()=>{customBackground=String(reader.result);render();$('[data-action=edit-bg]').focus();toast('Фон изменён в текущей сессии')};img.onerror=()=>toast('Не удалось прочитать изображение');img.src=String(reader.result)};reader.readAsDataURL(f)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#dialog').classList.contains('open'))closeFilm();if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-film]')){e.preventDefault();openFilm(+e.target.dataset.film)}});
document.addEventListener('pointerover',e=>{let f=e.target.closest('[data-film]');if(!f||page==='catalog'||e.pointerType==='touch'||reduced()||f.contains(e.relatedTarget))return;clearTimeout(hoverTimer);clearTimeout(restoreTimer);hoverTimer=setTimeout(()=>changeFocus(+f.dataset.film),theme==='experimental'?110:200)});
document.addEventListener('pointerout',e=>{let f=e.target.closest('[data-film]');if(!f||f.contains(e.relatedTarget))return;clearTimeout(hoverTimer);clearTimeout(restoreTimer);restoreTimer=setTimeout(restoreBackground,theme==='experimental'?480:320);let c=f.querySelector('.cover');['--rx','--ry','--ax','--ay'].forEach(p=>c.style.removeProperty(p));});
document.addEventListener('pointermove',e=>{let c=e.target.closest('.cover');if(!c||reduced()||e.pointerType==='touch'||page==='catalog')return;let r=c.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height)),m=theme==='depth'?1.5:theme==='scope'||theme==='iris'?.55:1;c.style.setProperty('--rx',(0.5-y)*8*m+'deg');c.style.setProperty('--ry',(x-.5)*9*m+'deg');c.style.setProperty('--ax',(x-.5)*-8+'px');c.style.setProperty('--ay',(y-.5)*-8+'px');c.style.setProperty('--px',x*100+'%');c.style.setProperty('--py',y*100+'%')});
document.addEventListener('focusin',e=>{let f=e.target.closest('[data-film]');if(f&&page!=='catalog'&&!reduced())changeFocus(+f.dataset.film)});document.addEventListener('focusout',e=>{let f=e.target.closest('[data-film]');if(f&&!f.contains(e.relatedTarget)){clearTimeout(restoreTimer);restoreTimer=setTimeout(restoreBackground,320)}});window.addEventListener('resize',positionTab);const initialView=new URLSearchParams(location.search).get('view');if(location.pathname==='/')page='home';else if(['catalog','rating','home','profile','library'].includes(initialView))page=initialView==='rating'?'catalog':initialView;if(page==='library')tab='Оценённые';render();if(initialView==='rating')openFilm(0);

function validDraft(){const i=draft.scores.findIndex((v,i)=>(i===0&&v===null)||(v!==null&&(!Number.isFinite(v)||v<0||v>10)));if(i<0)return true;const input=$(`#criterion-${i}`);input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby','score-help');$('#score-help').textContent=`${criteria[i]}: укажите значение от 0 до 10.`;input.focus();return false;}
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeFilm()});

// Keep keyboard navigation within the active modal, including reverse traversal.
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||!$('#dialog').open)return;const controls=[...$('#dialog').querySelectorAll('button,input,textarea')].filter(el=>!el.disabled&&el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
